<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';Auth::requireLogin();Auth::ensureUserSchema();$pdo=Database::connection();$message='';$error='';function role_label(string $r):string{return $r==='superadmin'?'SuperAdmin':'Administrator';}function load_user(PDO $p,int $id){$s=$p->prepare('SELECT * FROM users WHERE id=:id AND role IN ("admin","superadmin")');$s->execute(['id'=>$id]);return$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(!Auth::isSuperAdmin())throw new RuntimeException('Alleen een SuperAdmin kan beheerders wijzigen.');$a=(string)($_POST['action']??'');if($a==='create'){$n=trim((string)$_POST['name']);$e=strtolower(trim((string)$_POST['email']));$pw=(string)$_POST['password'];$r=in_array($_POST['role']??'', ['admin','superadmin'],true)?$_POST['role']:'admin';if($n===''||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)throw new RuntimeException('Naam, geldig e-mailadres en wachtwoord van minstens 10 tekens zijn verplicht.');$pdo->prepare('INSERT INTO users(name,email,password_hash,role,is_active) VALUES(:n,:e,:h,:r,1)')->execute(['n'=>$n,'e'=>$e,'h'=>password_hash($pw,PASSWORD_DEFAULT),'r'=>$r]);$message='Beheerder toegevoegd.';}else{$id=(int)($_POST['id']??0);$u=load_user($pdo,$id);if(!$u)throw new RuntimeException('Beheerder niet gevonden.');if($a==='toggle'){if($id===(int)$_SESSION['user_id'])throw new RuntimeException('Je kunt je eigen account niet deactiveren.');$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=:id')->execute(['id'=>$id]);$message='Status aangepast.';}elseif($a==='role'){$r=in_array($_POST['role']??'', ['admin','superadmin'],true)?$_POST['role']:'admin';if($id===(int)$_SESSION['user_id']&&$r!=='superadmin')throw new RuntimeException('Je kunt je eigen SuperAdmin-rechten niet verlagen.');$pdo->prepare('UPDATE users SET role=:r WHERE id=:id')->execute(['r'=>$r,'id'=>$id]);$message='Rol aangepast.';}elseif($a==='password'){$pw=(string)($_POST['password']??'');if(strlen($pw)<10)throw new RuntimeException('Wachtwoord moet minstens 10 tekens bevatten.');$pdo->prepare('UPDATE users SET password_hash=:h WHERE id=:id')->execute(['h'=>password_hash($pw,PASSWORD_DEFAULT),'id'=>$id]);$message='Wachtwoord aangepast.';}}}catch(Throwable $e){$error=$e->getMessage();}}$users=$pdo->query('SELECT * FROM users WHERE role IN ("admin","superadmin") ORDER BY FIELD(role,"superadmin","admin"),name')->fetchAll();?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beheer gebruikers</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0}header{background:#111;color:#fff;padding:18px 28px}main{max-width:1100px;margin:30px auto;padding:0 20px}.card{background:#fff;padding:22px;border-radius:14px;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;font-weight:700;margin:8px 0 5px}input,select{padding:10px;border:1px solid #ccd2d8;border-radius:8px;box-sizing:border-box;width:100%}.btn{padding:9px 12px;border:0;border-radius:8px;background:#111;color:#fff;font-weight:700;cursor:pointer}.secondary{background:#e8ebef;color:#111}.ok{background:#e9f8ee;padding:12px}.err{background:#feecec;padding:12px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.actions{display:flex;gap:6px;flex-wrap:wrap}.inline{display:flex;gap:5px}.pw{display:flex;gap:5px}.pw .eye{width:44px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><header>Heli One Members</header><main><h1>Beheer gebruikers</h1><p>Hier worden uitsluitend Administrator- en SuperAdmin-accounts beheerd. Ledenlogins beheer je voortaan via de ledenfiche.</p><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif;?><?php if($error):?><p class="err"><?=e($error)?></p><?php endif;?><?php if(Auth::isSuperAdmin()):?><div class="card"><h2>Beheerder toevoegen</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="grid"><div><label>Naam</label><input name="name" required></div><div><label>E-mail</label><input type="email" name="email" required></div><div><label>Wachtwoord</label><div class="pw"><input type="password" name="password" minlength="10" required><button class="btn secondary eye" type="button">👁</button></div></div><div><label>Rol</label><select name="role"><option value="admin">Administrator</option><option value="superadmin">SuperAdmin</option></select></div></div><p><button class="btn">Toevoegen</button></p></form></div><?php endif;?><div class="card"><table><thead><tr><th>Naam</th><th>Rol</th><th>Status</th><th>Laatste login</th><th>Acties</th></tr></thead><tbody><?php foreach($users as$u):?><tr><td><strong><?=e($u['name'])?></strong><br><?=e($u['email'])?></td><td><?=e(role_label($u['role']))?></td><td><?=$u['is_active']?'Actief':'Inactief'?></td><td><?=e($u['last_login_at']??'—')?></td><td><?php if(Auth::isSuperAdmin()):?><div class="actions"><?php if((int)$u['id']!==(int)$_SESSION['user_id']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button class="btn secondary"><?=$u['is_active']?'Deactiveren':'Activeren'?></button></form><?php endif;?><form method="post" class="inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><select name="role"><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Administrator</option><option value="superadmin" <?=$u['role']==='superadmin'?'selected':''?>>SuperAdmin</option></select><button class="btn secondary">Rol</button></form><form method="post" class="inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><div class="pw"><input type="password" name="password" minlength="10" placeholder="Nieuw wachtwoord" required><button class="btn secondary eye" type="button">👁</button></div><button class="btn secondary">Reset</button></form></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></main><script>document.querySelectorAll('.eye').forEach(b=>b.onclick=()=>{const i=b.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';});</script></body></html>